T.update({404: ('תשע מחלקות גדולות במקום עשרים ושתיים', 'Nine large sections instead of twenty-two departments'), 723: ('אני המייסד של Apps &amp; Soul.', 'I’m the founder of Apps &amp; Soul.'), 739: ('סל קניות, וההזמנה מגיעה לוואטסאפ כרשימה מוכנה', 'Cart, with orders sent to your WhatsApp as a ready list'), 130: ('הלקוח סורק ברקוד בטלפון, השם נשלף מהמאגר, והוא מוסיף מחיר ותמונה. הרשימה מגיעה לפאנל מוכנה.', 'The client scans a barcode, the name fills in from the database, and the client adds a price and photo. The list arrives in the panel ready.'), 374: ('פנו אליי אם אתם', 'Come to me if you'), 448: ('למה ישירות, ולא דרך סוכנות', 'Why directly, not through an agency'), 746: ('העברת המבחר מהקופה', 'Product range moved over from the till'), 757: ('עד&nbsp;1,000', 'up&nbsp;to&nbsp;1,000')})

T.update({758: ('הזמנות הלילה · דוגמה', 'orders tonight · example'), 759: ('הדגמה', 'Demo'), 760: ('כמה מכירות ערוץ אונליין יכול להוסיף', 'How many sales an online channel could add'), 761: ('ערוץ אונליין יכול להוסיף בערך', 'An online channel could add about'), 762: ('149,760 ₪ בשנה', '149,760 ₪ per year'), 763: ('12,480 ₪', '12,480 ₪'), 764: ('רוצה ערוץ מכירות כזה ←', 'I want this sales channel →'), 765: ('החישוב: קונים ביום × אחוז × קנייה ממוצעת × 26 ימי עבודה. זה תרחיש הכנסות, לא הבטחה לרווח.', 'Formula: customers per day × percent × average purchase × 26 working days. This is a revenue scenario, not a profit promise.'), 766: ('Apps & Soul — אתרים, חנויות ואפליקציות לעסקים', 'Apps & Soul — websites, online stores and apps for business'), 731: ('אתר תדמית', 'Business card'), 735: ('אני רוצה אתר תדמית', 'I want a business card site'), 754: ('חבילה 01 · אתר תדמית', 'PACKAGE 01 · BUSINESS CARD'), 384: ('רמה 1 · אתר תדמית', 'LEVEL 1 · BUSINESS CARD'), 19: ('אתר תדמית, דף נחיתה או אתר חברה.', 'Business card site, landing page or company site.'), 360: ('מקצה לקצה', 'turnkey'), 485: ('בונה אתרים, חנויות, אפליקציות וקטלוגים מקצה לקצה', 'I build sites, stores, apps and catalogs, turnkey')})

