T.update({774: ('מסכים אמיתיים', 'Real screens'), 775: ('לחצו להגדלה', 'tap to enlarge'), 776: ('Discovery Radar', 'Discovery Radar'), 777: ('מעבדת רעיונות.', 'An idea lab.'), 778: ('רעיונות טובים לעסק הולכים לאיבוד בין אלפי כתבות וסרטונים.', 'Good business ideas get lost among thousands of articles and videos.'), 779: ('האפליקציה מציגה תגלית מפתיעה, מסבירה אותה במילים פשוטות ומציעה איך ליישם. מצב „עזרו לי לפתור משימה”: למשל לנסוע פחות או פחות טעויות בהזמנות.', 'The app shows an unexpected discovery, explains it simply and suggests how to apply it. “Help me solve a task” mode: for example, drive less or make fewer order mistakes.'), 780: ('רעיון עם תועלת מיידית: בדוגמה הלימודית אותו מסלול של 10 נקודות מתקצר ב-54.4%.', 'An idea with immediate value: in the training example the same 10-stop route gets 54.4% shorter.'), 781: ('„הפתיעו אותי”: תגלית ורעיון ליישום', '“Surprise me”: a discovery and how to use it'), 782: ('„עזרו לי לפתור משימה” עם חישוב מוכן', '“Help me solve a task” with a ready calculation'), 783: ('מפת הרעיונות שלי ושמורים', 'My idea map and saved items')})

