T.update({381: ('חבילות בפעולה', 'Packages in action'), 417: ('04 — עבודות', '04 — Work'), 425: ('08 — תהליך', '08 — Process'), 445: ('09 — אחריות', '09 — Guarantees'), 461: ('10 — עליי', '10 — About me'), 468: ('11 — שאלות', '11 — FAQ'), 786: ('07 — נסו בעצמכם', '07 — Try it yourself'), 787: ('בנו את האתר שלכם, חשבו מכירות או שחקו 15 שניות. בחרו לשונית.', 'Build your site, estimate sales or play for 15 seconds. Pick a tab.'), 788: ('לנסות', 'Try it')})

