T.update({791: ('אפליקציה לעסק שלכם — שתי דרכים', 'An app for your business — two ways'), 792: ('בחרו מה שמתאים לכם. אפשר להתחיל בראשונה ולעבור אחר כך לשנייה: האתר, המוצרים וההזמנות נשארים.', 'Pick what fits you. You can start with the first and move to the second later: the site, products and orders stay.'), 793: ('אפליקציה על מסך הטלפון', 'An app on the phone screen'), 794: ('מהיר · בלי חנויות אפליקציות', 'Fast · no app stores'), 795: ('הלקוח פותח את האתר שלכם בטלפון.', 'The customer opens your site on the phone.'), 796: ('iPhone: כפתור „שיתוף” ← „הוספה למסך הבית”. Android: „התקנת אפליקציה”.', 'iPhone: “Share” → “Add to Home Screen”. Android: “Install app”.'), 797: ('על המסך מופיע הסמל של החנות שלכם. נפתח בנגיעה אחת, כמו אפליקציה רגילה.', 'Your shop’s icon appears on the screen. It opens with one tap, like a regular app.'), 798: ('סמל עם הלוגו שלכם ליד האפליקציות האחרות', 'An icon with your logo next to other apps'), 799: ('נפתח במסך מלא, בלי שורת כתובת', 'Opens full screen, no address bar'), 800: ('לא צריך לחכות לבדיקה של Apple ו-Google', 'No waiting for Apple and Google review'), 801: ('עדכונים מגיעים לכולם מיד, בלי הורדה', 'Updates reach everyone at once, no download'), 802: ('כמעט לא תופס זיכרון בטלפון', 'Takes almost no phone storage'), 803: ('בלי תשלום שנתי לחנויות האפליקציות', 'No yearly fee to app stores'), 804: ('לא מוצאים אותה בחיפוש ב-App Store וב-Google Play: הלקוח מתקין אותה מהאתר שלכם', 'It isn’t found by search in App Store or Google Play: customers install it from your site'), 805: ('ב-iPhone התראות עובדות רק אחרי התקנה למסך', 'On iPhone, notifications work only after installing to the screen'), 806: ('מה חשוב לדעת', 'Good to know'), 807: ('נסו: התקינו את האתר הזה', 'Try it: install this site'), 808: ('איך זה עובד', 'How it works'), 809: ('יתרונות', 'Advantages'), 810: ('אפליקציה מלאה ב-App Store וב-Google Play', 'A full app in App Store and Google Play'), 811: ('מקסימום אפשרויות', 'Maximum capabilities'), 812: ('אני בונה אפליקציה ל-iPhone ול-Android על בסיס האתר ומאגר המוצרים שלכם.', 'I build an iPhone and Android app based on your site and product base.'), 813: ('פותחים חשבונות מפתח על שם העסק שלכם.', 'We open developer accounts in your business’s name.'), 814: ('אני מגיש את האפליקציה לחנויות ועובר את הבדיקה של Apple ו-Google.', 'I submit the app to the stores and pass Apple and Google review.'), 815: ('האפליקציה מופיעה בחיפוש ב-App Store וב-Google Play.', 'The app appears in App Store and Google Play search.'), 816: ('לקוחות מוצאים אתכם בחיפוש בחנויות האפליקציות', 'Customers find you by searching the app stores'), 817: ('יותר אמון: „יש להם אפליקציה משלהם”', 'More trust: “they have their own app”'), 818: ('התראות על מבצעים בכל הטלפונים', 'Promotion notifications on all phones'), 819: ('גישה מלאה למצלמה, לסורק ולמיקום', 'Full access to camera, scanner and location'), 820: ('חשבונות מפתח: Apple — \u200f99$ בשנה, Google — \u200f25$ פעם אחת. משלם בעל העסק', 'Developer accounts: Apple $99 a year, Google $25 once. Paid by the business owner'), 821: ('הבדיקה של Apple לוקחת זמן, וגם עדכונים עוברים בדיקה', 'Apple review takes time, and updates are reviewed too'), 822: ('את עלות הפיתוח אמסור אחרי שיחה קצרה', 'I’ll quote the development cost after a short call'), 823: ('העצה שלי: התחילו בדרך הראשונה. כשיהיו יותר לקוחות, נעבור לשנייה.', 'My advice: start with the first way. When you have more customers, we’ll move to the second.'), 824: ("'ב-iPhone: לחצו למטה על „שיתוף” (ריבוע עם חץ), אחר כך „הוספה למסך הבית” ו„הוספה”.'", "'On iPhone: tap “Share” at the bottom (square with an arrow), then “Add to Home Screen” and “Add”.'"), 825: ("'ב-Android: לחצו על התפריט ⋮ בדפדפן ובחרו „התקנת אפליקציה” או „הוספה למסך הבית”.'", "'On Android: tap the ⋮ menu in the browser and choose “Install app” or “Add to Home screen”.'"), 826: ("'האתר כבר מותקן ופתוח כאפליקציה.'", "'The site is already installed and open as an app.'"), 827: ("'במחשב: ב-Chrome או ב-Edge לחצו על סמל ההתקנה בצד שורת הכתובת. בטלפון פתחו את האתר הזה ופעלו לפי השלבים למעלה.'", "'On a computer: in Chrome or Edge click the install icon in the address bar. On a phone, open this site and follow the steps above.'")})

T.update({828: ('חשוב: זה לא אותו דבר.', 'Important: these are not the same thing.'), 829: ('הדרך הראשונה — האתר שלכם, שמותקן על מסך הטלפון כמו אפליקציה. השנייה — אפליקציה נפרדת שעוברת בדיקה של Apple ו-Google ונמצאת בחנויות שלהן. האפשרויות, הזמנים והעלויות שונים.', 'The first way is your website, installed on the phone screen like an app. The second is a separate app that passes Apple and Google review and lives in their stores. Capabilities, timelines and costs differ.')})

T.update({36: ('שתי דרכים: ישר מהאתר או מ-App Store ו-Google Play.', 'Two ways: straight from the site or from the App Store and Google Play.'), 37: ('הדרך המהירה — אייקון על המסך ישר מהאתר. הדרך המלאה — אפליקציה ב-App Store וב-Google Play. זה לא אותו דבר: ההבדל מוסבר בבלוק „אפליקציה לעסק שלכם”.', 'The quick way is an icon on the screen straight from the site. The full way is an app in the App Store and Google Play. They are not the same: the difference is explained in the “An app for your business” block.'), 38: ('מהאתר: מהיר, בלי תשלום לחנויות האפליקציות', 'From the site: quick, no app store fees'), 39: ('ב-App Store וב-Google Play: לוקח יותר זמן, עולה יותר, ויש תשלום לחנויות', 'In the App Store and Google Play: longer, pricier, plus store fees'), 40: ('את הדרך בוחרים אחרי שיחה על המשימה', 'We choose the way after discussing the task'), 329: ('יש שתי דרכים. אפליקציה מהאתר — מהירה וזולה יותר, אבל עם מגבלות. אפליקציה מלאה ב-App Store וב-Google Play — לוקחת יותר זמן ועולה יותר, ויש תשלום לחנויות: Apple — \u200f99$ בשנה, Google — \u200f25$ פעם אחת. ההבדל מוסבר בפירוט בחלק „שירותים”.', 'There are two ways. An app from the site is faster and cheaper, but has limits. A full app in the App Store and Google Play takes longer and costs more, plus store fees: Apple $99 a year, Google $25 once. The difference is explained in detail in the “Services” section.'), 314: ('סקיצה אני מציג תוך 3–5 ימים. הזמן הכולל תלוי במשימה: אתר תדמית נבנה מהר יותר, חנות או אפליקציה לוקחות יותר. זמן מדויק אני נותן לפני תחילת העבודה.', 'I show a mockup within 3–5 days. Total time depends on the task: a business card site is faster, a store or app takes longer. I give an exact timeline before work starts.'), 22: ('נוח בטלפון, בטאבלט ובמסך גדול', 'Works well on phones, tablets and large screens'), 736: ('חנות', 'Store'), 738: ('חנות אונליין עם קטלוג וסל', 'Online store with catalog and cart'), 741: ('אני רוצה חנות', 'I want a store'), 744: ('כמה חנויות, אפליקציה, מערכת משלכם', 'Several stores, an app, your own system'), 745: ('כמה חנויות בסל אחד', 'Several stores in one cart'), 743: ('3,000 מוצרים ומעלה', '3,000+ products')})

T.update({830: ('<h3>תנאי עבודה</h3>', '<h3>Terms of work</h3>'), 831: ('<p>בקצרה ובכנות: איך נקבע המחיר, מה כלול בעבודה ומה נשאר באחריותכם.</p>', '<p>Short and honest: how the price is set, what the work includes and what stays on your side.</p>'), 832: ('<h4>מחיר ותוכנית</h4>', '<h4>Price and plan</h4>'), 833: ('<p>המחירים „החל מ” באתר הם להתמצאות. לפני תחילת העבודה תקבלו תוכנית כתובה: מה כלול, כמה זה עולה ובאיזה לוח זמנים. כל מה שלא נכלל בתוכנית מתומחר בנפרד ורק בהסכמתכם.</p>', '<p>The “from” prices on the site are a guide. Before work starts you get a written plan: what’s included, what it costs and the timeline. Anything outside the plan is priced separately and only with your consent.</p>'), 834: ('<h4>תשלום בשלבים</h4>', '<h4>Payment in stages</h4>'), 835: ('<p>40% בהתחלה, 40% אחרי אישור הסקיצה, 20% בהשקה.</p>', '<p>40% at the start, 40% after the mockup is approved, 20% at launch.</p>'), 836: ('<h4>סקיצה ותיקונים</h4>', '<h4>Mockup and revisions</h4>'), 837: ('<p>קודם סקיצה, ואחר כך פיתוח. תיקונים בסקיצה מתבצעים עד שהיא מאושרת. אחרי האישור, שינויי עיצוב ופיצ׳רים חדשים מתומחרים בנפרד.</p>', '<p>Mockup first, then development. Mockup revisions are made until it is approved. After approval, design changes and new features are priced separately.</p>'), 838: ('<h4>לוחות זמנים</h4>', '<h4>Timelines</h4>'), 839: ('<p>סקיצה — תוך 3–5 ימים מקבלת החומרים. הזמן הכולל מופיע בתוכנית. אם טקסטים, תמונות או רשימת מוצרים מגיעים מאוחר יותר, המועד זז בהתאם.</p>', '<p>The mockup comes 3–5 days after the materials arrive. The total timeline is in the plan. If texts, photos or the product list arrive later, the deadline moves by the same amount.</p>'), 840: ('<h4>מה שייך לכם</h4>', '<h4>What belongs to you</h4>'), 841: ('<p>האתר המוכן, הטקסטים, התמונות והנתונים שלכם, וכתובת האתר. הגישות נמסרות לכם בהשקה. אם האתר מאוחסן אצל הסטודיו במסגרת ליווי, הגישות ועותק של הקוד נמסרים לפי בקשה ראשונה.</p>', '<p>The finished site, your texts, photos and data, and the site address. Access is handed to you at launch. If the site is hosted by the studio as part of support, access and a copy of the code are handed over on first request.</p>'), 842: ('<h4>שירותים חיצוניים</h4>', '<h4>Third-party services</h4>'), 843: ('<p>אחסון, דומיין, WhatsApp Business, שירותים לעוזר ה-AI, App Store ו-Google Play הם חברות נפרדות עם תנאים ומחירים משלהן. החשבונות נפתחים על שמכם, ואתם משלמים להן ישירות. העלות נמסרת מראש.</p>', '<p>Hosting, the domain, WhatsApp Business, AI assistant services, the App Store and Google Play are separate companies with their own terms and prices. Accounts are opened in your name and you pay them directly. Costs are stated in advance.</p>'), 844: ('<h4>אחרי ההשקה</h4>', '<h4>After launch</h4>'), 845: ('<p>ליווי — במנוי: החל מ-250 ₪ לחודש, לחנות החל מ-490 ₪. אפשר גם בלי מנוי: עבודות חד־פעמיות מתומחרות בנפרד.</p>', '<p>Support is by subscription: from 250 ₪ a month, from 490 ₪ for a store. You can also go without one: one-off jobs are priced separately.</p>'), 846: ('<p>אם משהו לא ברור — שאלו לפני תחילת העבודה.</p>', '<p>If anything is unclear, ask before work starts.</p>'), 847: ('>תנאי עבודה<', '>Terms of work<'), 848: (' בפירוט — ב<button type="button" class="lk" data-open="dT">תנאי העבודה</button>.', ' Details are in the <button type="button" class="lk" data-open="dT">terms of work</button>.')})

T.update({849: ('סרטון · 17 שניות</button>', 'Video · 17 seconds</button>'), 850: ('aria-label="סרטון"', 'aria-label="Video"')})

T.update({851: ('אתם מדברים עם מי שבונה', 'You talk to the one who builds'), 852: ('בדרך כלל בסוכנות מדברים עם מנהל פרויקט, ואת העבודה עושים אנשים אחרים. כאן מדבר איתכם מי שבונה בעצמו את הפרויקט שלכם.', 'At an agency you usually deal with a manager while other people do the work. Here you talk to the person who builds your project himself.'), 853: ('בכל יום ידוע איפה הפרויקט עומד', 'Where the project stands — known any day'), 854: ('לא צריך לחכות שהמנהל יברר מול הצוות: אני יודע באיזה שלב נמצא כל פרט.', 'No waiting while a manager checks with the team: I know the stage of every detail.'), 855: ('תיקונים בלי טלפון שבור', 'Revisions without retelling'), 856: ('המילים שלכם לא עוברות בשרשרת שבה חלק מהמשמעות הולך לאיבוד. מה שאמרתם — זה מה שאני עושה.', 'Your words don’t pass down a chain where part of the meaning gets lost. What you say is what I do.'), 857: ('החלטות מיד', 'Decisions on the spot'), 858: ('בלי ישיבות ואישורים פנימיים: שאלה — תשובה.', 'No internal meetings or sign-offs: question, answer.'), 859: ('<p>הרבה אי־הבנות בסטודיואים גדולים נוצרות כי הלקוח מדבר לא עם מי שעושה את העבודה. כאן אין מתווך כזה.</p>', '<p>Many misunderstandings at big studios happen because the client doesn’t talk to the person doing the work. Here there is no such middleman.</p>')})

T.update({860: ('בזמן שאתם ישנים, החנות שלכם <em>עובדת</em>: מקבלת הזמנות ואוספת סלים. אתם מתעוררים — <em>וההזמנות כבר בוואטסאפ</em>.', 'While you sleep, your store <em>keeps working</em>: taking orders and filling carts. You wake up — <em>and the orders are already in WhatsApp</em>.'), 861: ('aria-label="המסר המרכזי"', 'aria-label="Main idea"'), 862: ('אזרט — שלוש חנויות, סל אחד, 4,800 מוצרים', 'Azart — three stores, one cart, 4,800 products'), 863: ('alt="חנות אזרט במחשב"', 'alt="Azart store on a computer"')})

T.update({419: ('חנויות, תוכנות, אפליקציות וקטלוגים. גררו את השולחן בעכבר או באצבע, לחצו על מסך — ייפתח הסיפור: משימה, פתרון ומה בפנים.', 'Stores, programs, apps and catalogs. Drag the table with your mouse or finger, tap a screen to open its story: task, solution and what’s inside.'), 725: ('אני אדם עם נשמה של אמן, ואוהב כשדבר לא רק עובד אלא גם משמח את העין. מעצב בעצמי ובונה קטלוגים. וכל פרויקט של לקוח אני מוביל כאילו הוא שלי.', 'I’m an artistic person and I love it when something not only works but is a pleasure to look at. I do the design myself and build catalogs. And I treat every client project as if it were my own.')})

T.update({864: ("'חנות אונליין'", "'Online store'"), 865: ("'חנות אונליין עם תצוגה כמו בסופרמרקט'", "'Online store with a supermarket-style shelf'"), 866: ("'חנות מלאה באינטרנט: מחלקות ומדפים, חיפוש חכם, מבצעים, מארזים והזמנה ישר לוואטסאפ. בלי מתווכים ובלי תוספות מחיר של אחרים.'", "'A full online store: departments and shelves, smart search, promotions, gift sets and ordering straight to WhatsApp. No middlemen, no third-party markups.'"), 867: ("'החנות תלויה בשירות משלוחים עם מחירים מנופחים וכללים של אחרים, והקונה לא רואה את המחירים האמיתיים.'", "'The store depends on a delivery service with inflated prices and someone else’s rules, and shoppers never see the real prices.'"), 868: ("'חנות משלכם: המוצרים מסודרים כמו בסופרמרקט (מחלקה ← קבוצה ← מדף), החיפוש מבין שגיאות כתיב וקול, והסל שולח את ההזמנה לוואטסאפ של החנות כרשימה מוכנה.'", "'Your own store: products are laid out like a supermarket (department → group → shelf), search understands typos and voice, and the cart sends the order to the store’s WhatsApp as a ready list.'"), 869: ("'החנות מוכרת ישירות, במחירים ובכללים שלה, והבעלים מנהלים הכול בעצמם.'", "'The store sells directly, at its own prices and on its own terms, and the owner runs everything.'"), 870: ("'תצוגה „מחלקה ← קבוצה ← מדף״, כמו בסופרמרקט גדול'", "'“Department → group → shelf” layout, like a big supermarket'"), 871: ("'חיפוש שמבין שגיאות כתיב וחיפוש קולי'", "'Typo-tolerant search and voice search'"), 872: ("'ארץ ייצור עם דגל, משקל ונפח לכל מוצר'", "'Country of origin flag, weight and volume for each product'"), 873: ("'מוצרים במשקל — הזמנה בגרמים'", "'Products sold by weight — order in grams'"), 874: ("'מבצעים עם פס על כל הסל: הנחה, משלוח חינם, 1+1'", "'Promotions with a banner across the cart: discount, free delivery, 1+1'"), 875: ("'מארזי חג ועמוד-בונה „שולחן החג״'", "'Holiday sets and a “Holiday table” builder page'"), 876: ("'מחלקת 18+ עם אימות גיל'", "'18+ department with age check'"), 877: ("'אזורי משלוח וסכום הזמנה מינימלי'", "'Delivery zones and a minimum order'"), 878: ("'שלוש שפות ופריסה מיוחדת למסכים רחבים במיוחד'", "'Three languages and a special layout for ultra-wide screens'"), 879: ("'מותקנת בטלפון כמו אפליקציה'", "'Installs on the phone like an app'"), 880: ("'תשלום אונליין בכרטיס וב-Bit'", "'Online payment by card and Bit'"), 881: ("'מועדון לקוחות עם נקודות'", "'Loyalty club with points'"), 882: ("'עוזר AI שעונה ללקוחות בוואטסאפ'", "'AI assistant that answers customers on WhatsApp'"), 883: ("'אפליקציה ב-App Store וב-Google Play'", "'App in the App Store and Google Play'"), 884: ("'מעדנייה: כ-900 מוצרים, בעברית, ברוסית ובאנגלית.'", "'Delicatessen: about 900 products in Hebrew, Russian and English.'"), 885: ("'פועל'", "'Live'"), 886: ("'כמה חנויות — סל אחד'", "'Several stores — one cart'"), 887: ("'אתר אחד לכל החנויות של הבעלים: סל משותף, הזמנה אחת, וכל המבחר עבר ישירות מהקופה.'", "'One site for all of the owner’s stores: a shared cart, one order, and the whole range moved straight from the till.'"), 888: ("'לבעלים יש כמה חנויות שונות, ולא נוח לקונה לבצע כמה הזמנות.'", "'The owner has several different stores, and ordering from each separately is inconvenient for shoppers.'"), 889: ("'אתר אחד מאחד את כל החנויות: למעלה החנויות של הבעלים, מתחת סרט פוסטרים ומחלקות גדולות. המבחר נטען מקובץ הקופה, והסל משותף.'", "'One site brings all the stores together: the owner’s stores on top, a poster strip and large sections below. The range is loaded from the till file, and the cart is shared.'"), 890: ("'הקונה מזמין הכול בפעם אחת, והבעלים מקבלים הזמנה אחת ברורה.'", "'Shoppers order everything at once, and the owner receives one clear order.'"), 891: ("'סל משותף והזמנה אחת לכל החנויות'", "'Shared cart and one order for all stores'"), 892: ("'העברת כל המבחר מהקופה'", "'Whole range transferred from the till'"), 893: ("'מחלקות גדולות במקום עשרות מחלקות קטנות'", "'Large sections instead of dozens of small departments'"), 894: ("'סרט פוסטרים עם מבצעים בדף הבית'", "'Poster strip with promotions on the home page'"), 895: ("'כניסה נפרדת 18+ לאלכוהול'", "'Separate 18+ entrance for alcohol'"), 896: ("'משלוח בעיר וסכום הזמנה מינימלי'", "'Delivery in town and a minimum order'"), 897: ("'תשלום במסירה: מזומן, Bit, כרטיס'", "'Payment on delivery: cash, Bit, card'"), 898: ("'עברית, רוסית ואנגלית'", "'Hebrew, Russian and English'"), 899: ("'סנכרון מחירים ומלאי עם הקופה'", "'Price and stock sync with the till'"), 900: ("'תשלום אונליין'", "'Online payment'"), 901: ("'חנויות וסניפים חדשים באותו סל'", "'New stores and branches in the same cart'"), 902: ("'אזור אישי לקונה עם היסטוריית הזמנות'", "'Customer account with order history'"), 903: ("'שלוש חנויות באשקלון: כמעט 4,800 מוצרים באתר אחד.'", "'Three stores in Ashkelon: almost 4,800 products on one site.'"), 904: ("'בהשקה'", "'Launching'"), 905: ("'פאנל ניהול'", "'Admin panel'"), 906: ("'פאנל ניהול לחנות'", "'Store admin panel'"), 907: ("'כל החנות בחלון אחד במחשב ובטלפון: הזמנות, מוצרים, מבצעים, ספקים, כסף ודוחות.'", "'The whole store in one window on computer and phone: orders, products, promotions, suppliers, money and reports.'"), 908: ("'הבעלים עובדים בעשר תוכנות ועדיין לא רואים את התמונה המלאה.'", "'The owner works in ten programs and still can’t see the full picture.'"), 909: ("'הפאנל מציג סיכום יומי, מנהל הזמנות לפי סטטוס, מוצרים ומבצעים, ספקים ותוקף, בונה דוחות ורושם כל פעולה.'", "'The panel shows a daily summary, manages orders by status, products and promotions, suppliers and expiry dates, builds reports and logs every action.'"), 910: ("'הבעלים מנהלים את החנות מהטלפון ורואים הכול במקום אחד.'", "'The owner runs the store from the phone and sees everything in one place.'"), 911: ("'סיכום יומי: מכירות, הזמנות חדשות, מה נגמר'", "'Daily summary: sales, new orders, what ran out'"), 912: ("'הזמנות לפי סטטוס: חדשות, בטיפול, מוכנות'", "'Orders by status: new, in progress, ready'"), 913: ("'עדכון מוצרים במקבצים וביטול מקבץ בלחיצה'", "'Batch product edits and one-click batch undo'"), 914: ("'„הגיע היום״, תוקף, ספקים'", "'“Arrived today”, expiry dates, suppliers'"), 915: ("'מבצעים: הנחה, משלוח חינם, 1+1'", "'Promotions: discount, free delivery, 1+1'"), 916: ("'דוחות: מכירות, רווח, הוצאות'", "'Reports: sales, profit, expenses'"), 917: ("'עובדים עם הרשאות שונות'", "'Staff with different permissions'"), 918: ("'כניסה עם קוד מאפליקציה ויומן של כל הפעולות'", "'Sign-in with an authenticator code and a log of every action'"), 919: ("'חיבור לקופה ולהנהלת חשבונות'", "'Connection to the till and accounting'"), 920: ("'התראות על הזמנות חדשות בטלפון'", "'New order notifications on the phone'"), 921: ("'ניהול עובדים ומשמרות'", "'Staff and shift management'"), 922: ("'כל דוח שהעסק שלכם צריך'", "'Any report your business needs'"), 923: ("'פועל במעדנייה.'", "'Running at the delicatessen.'"), 924: ("'כלי'", "'Tool'"), 925: ("'עוזר להעלאת מוצרים ולספירת מלאי'", "'Product upload and stock count assistant'"), 926: ("'הלקוח סורק ברקוד בטלפון — השם מגיע מהמאגר שלנו, מוסיף מחיר ותמונה. ויש גם מצב ספירת מלאי עם פרוטוקול מוכן.'", "'The client scans a barcode with the phone — the name comes from our own database, then adds a price and photo. Plus a stock count mode with a ready protocol.'"), 927: ("'רשימות מוצרים מגיעות בתמונות ובהודעות: לוקח זמן לפענח, וקל לטעות.'", "'Product lists arrive as photos and messages: slow to sort out and easy to get wrong.'"), 928: ("'הלקוח פותח קישור אישי, סורק מוצרים, מציין מחיר וכמות, מוסיף תמונה ושולח. הכול מגיע לפאנל, מסודר לפי לקוחות.'", "'The client opens a personal link, scans products, enters price and quantity, adds a photo and sends. Everything arrives in the panel, sorted by client.'"), 929: ("'המוצרים עולים לאתר מהר ובלי טעויות, וספירת המלאי הופכת למסמך מוכן.'", "'Products reach the site quickly and without errors, and a stock count becomes a ready document.'"), 930: ("'סורק ברקוד במצלמה, מתמונה או בהקלדה, עם פנס'", "'Barcode scanning by camera, photo or typing, with a flashlight'"), 931: ("'מאגר משלנו של יותר מ-109,000 ברקודים מרשתות בישראל'", "'Our own database of 109,000+ barcodes from Israeli chains'"), 932: ("'אם המוצר לא במאגר — השם מוקלד פעם אחת'", "'If a product isn’t in the database, its name is typed once'"), 933: ("'מחיר, כמות ותמונה לכל שורה'", "'Price, quantity and photo for each line'"), 934: ("'הרשימה נשמרת בטלפון עד השליחה, שליחה לשרת או לוואטסאפ'", "'The list stays on the phone until sent, to the server or WhatsApp'"), 935: ("'מצב „ספירת מלאי״: סריקה חוזרת מוסיפה יחידה'", "'“Stock count” mode: scanning again adds a unit'"), 936: ("'פרוטוקול ספירת מלאי להדפסה, PDF ו-Excel: עלות, מחיר שוק, חתימות'", "'Stock count protocol for print, PDF and Excel: cost, market price, signatures'"), 937: ("'פאנל: דוחות חדשים, פתוחים וגמורים, תיקייה לכל לקוח'", "'Panel: new, open and finished reports, a folder for each client'"), 938: ("'שליחת כל המוצרים למאגר בלחיצה, ייצוא ל-Excel'", "'Send all products to the database in one click, export to Excel'"), 939: ("'קישור אישי לכל לקוח בעברית או ברוסית'", "'Personal link for each client in Hebrew or Russian'"), 940: ("'זיהוי מוצר לפי תמונה בלי ברקוד'", "'Product recognition by photo without a barcode'"), 941: ("'תיאורי מוצרים אוטומטיים'", "'Automatic product descriptions'"), 942: ("'העלאה ישירה לכל אתר ולקופה'", "'Direct upload to any site and till'"), 943: ("'ספירת מלאי שנתית לעסק מקצה לקצה'", "'Annual stock count for a business, end to end'"), 944: ("'משמש למילוי חנויות אונליין של לקוחות.'", "'Used to fill clients’ online stores.'"), 945: ("'אפליקציה'", "'App'"), 946: ("'„מדף״ — ספירת מלאי בחנות'", "'“Shelf” — stock count in the store'"), 947: ("'העיקר — ספירת מלאי: סורקים מוצר בטלפון ורואים מיד כמה יש ומה חסר. הבסיס לכל מה שקשור למוצר בחנות.'", "'The core is counting stock: scan a product with the phone and see right away how much is left and what’s missing. The base for everything to do with products in a store.'"), 948: ("'הבעלים לא יודעים בדיוק כמה סחורה נשארה, סופרים עם מחברת ושוכחים מה להזמין.'", "'The owner doesn’t know exactly how much stock is left, counts with a notebook and forgets what to order.'"), 949: ("'הטלפון סורק את המוצר, והשם מגיע ממאגר הברקודים שלנו. לכל מוצר מגדירים מינימום, והאפליקציה מראה מה תקין, מה מתחת למינימום, ובונה הזמנה לבד.'", "'The phone scans the product and the name comes from our barcode database. Each product gets a minimum; the app shows what’s fine, what’s below minimum, and builds the order by itself.'"), 950: ("'המלאי תמיד ידוע, הספירה לוקחת דקות, וההזמנה מוכנה בלי מחברות.'", "'Stock is always known, counting takes minutes, and the order is ready without notebooks.'"), 951: ("'ספירת מלאי בסורק המצלמה או ידנית'", "'Stock count with the camera scanner or by hand'"), 952: ("'שם המוצר ממאגר הברקודים שלנו'", "'Product name from our barcode database'"), 953: ("'ספק וגודל קרטון לכל מוצר'", "'Supplier and case size for each product'"), 954: ("'מינימום על המדף וסטטוס „תקין״ / „מתחת למינימום״'", "'Shelf minimum and “OK” / “below minimum” status'"), 955: ("'סיכום: נספר היום, מתחת למינימום, לא במאגר'", "'Summary: counted today, below minimum, not in database'"), 956: ("'הזמנה נפרדת לכל ספק כהודעה מוכנה בוואטסאפ'", "'A separate order for each supplier as a ready WhatsApp message'"), 957: ("'עברית — השפה הראשית, ובנוסף רוסית ואנגלית'", "'Hebrew as the main language, plus Russian and English'"), 958: ("'קבלת סחורה לפי תעודת משלוח: התאמה מול ההזמנה'", "'Receiving by delivery note: checking against the order'"), 959: ("'תוקף עם התראה מראש'", "'Expiry dates with an early warning'"), 960: ("'מדבקות ותוויות עם ברקוד'", "'Price tags and labels with barcodes'"), 961: ("'משימות לעובדים: מי בודק מה היום'", "'Staff tasks: who checks what today'"), 962: ("'חובות לקוחות ורשימת המתנה „נודיע כשיגיע״'", "'Customer debts and a “we’ll let you know” waiting list'"), 963: ("'ייבוא מחירונים והשוואת מחירי ספקים'", "'Importing price lists and comparing supplier prices'"), 964: ("'דוח לרואה החשבון עם מע״מ'", "'Accountant report with VAT'"), 965: ("'ספירה לפי תמונת מדף והקלדה קולית'", "'Counting from a shelf photo and voice input'"), 966: ("'סיכום בוקר: מה דורש תשומת לב'", "'Morning summary: what needs attention'"), 967: ("'מאגר משותף לטלפון, לאייפד ולמחשב'", "'Shared data for phone, iPad and computer'"), 968: ("'נבנית לחנויות מזון; רשימת הפיתוח כבר מובנית באפליקציה.'", "'Being built for grocery stores; the development list is already in the app.'"), 969: ("'בפיתוח'", "'In development'"), 970: ("'עוזר'", "'Assistant'"), 971: ("'עוזר לסוכן מכירות'", "'Sales agent assistant'"), 972: ("'מתכנן את היום של הסוכן: כל הלקוחות על מפה אינטראקטיבית, סימונים, הערות, מסלול ו„מי לידי״. כל מספר נקודות, כל אזור.'", "'Plans the agent’s day: all clients on an interactive map, marks, notes, a route and “who’s near me”. Any number of points, any area.'"), 973: ("'לסוכן יש מאות נקודות, קשה לתכנן את היום וקל לשכוח לקוח.'", "'An agent has hundreds of points: hard to plan the day, easy to forget a client.'"), 974: ("'כל הנקודות על המפה עם סימון „לקוח / לא לקוח״, הערות ומסננים. העוזר בונה מסלול ליום, מראה מי בקרבת מקום ומזכיר למי הגיע הזמן לחזור.'", "'All points on the map marked “client / not a client”, with notes and filters. The assistant builds a route for the day, shows who’s nearby and reminds you whom to revisit.'"), 975: ("'פחות קילומטרים מיותרים, אף לקוח לא נשכח, והיום מתוכנן בדקה.'", "'Fewer wasted kilometres, no client forgotten, the day planned in a minute.'"), 976: ("'מפה אינטראקטיבית של כל הנקודות באזור'", "'Interactive map of every point in the area'"), 977: ("'סימון לקוחות והערות לכל נקודה'", "'Client marks and notes for each point'"), 978: ("'מסננים: לקוחות, ביקורים, „לחזור בעוד 30 יום״'", "'Filters: clients, visits, “come back in 30 days”'"), 979: ("'מסלול ליום'", "'Route for the day'"), 980: ("'„לידי״ לפי המיקום הנוכחי'", "'“Near me” by current location'"), 981: ("'הזמנות ישר מהמפה'", "'Orders straight from the map'"), 982: ("'דוחות ביקורים למנהל'", "'Visit reports for the manager'"), 983: ("'עבודה של צוות סוכנים שלם'", "'Work for a whole team of agents'"), 984: ("'חיבור לאפליקציית הסוכן ול-CRM'", "'Connection to the agent app and CRM'"), 985: ("'כרגע מוגדר לקו מתל אביב עד קריית שמונה: 307 נקודות ב-55 ערים. להוסיף עוד מאות נקודות — אין בעיה.'", "'Currently set up for the Tel Aviv to Kiryat Shmona line: 307 points in 55 towns. Adding hundreds more is no problem.'"), 986: ("'קטלוג'", "'Catalog'"), 987: ("'מחירון עם הזמנה בוואטסאפ'", "'Price list with WhatsApp ordering'"), 988: ("'קטלוג בטלפון: הקונה בוחר מוצרים בקרטונים או ביחידות, וההזמנה יוצאת לוואטסאפ כרשימה מוכנה.'", "'A catalog on the phone: shoppers pick products by the case or by the unit, and the order goes to WhatsApp as a ready list.'"), 989: ("'הקונים מזמינים בטלפון, מתבלבלים בפריטים, והמוכר מבזבז זמן על התכתבויות.'", "'Customers order by phone, mix up items, and the seller wastes time on messages.'"), 990: ("'המחירון נפתח בקישור, מחפשים מוצרים לפי שם וברקוד, והסל מחשב את הסכום ושולח את ההזמנה למוכר.'", "'The price list opens from a link, products are found by name and barcode, and the cart totals the sum and sends the order to the seller.'"), 991: ("'הזמנה בלי טעויות ובלי שיחות.'", "'Orders without mistakes and without calls.'"), 992: ("'הזמנה בקרטונים או ביחידות'", "'Order by the case or by the unit'"), 993: ("'חיפוש לפי שם וברקוד'", "'Search by name and barcode'"), 994: ("'ארבע שפות: עברית, ערבית, רוסית, אנגלית'", "'Four languages: Hebrew, Arabic, Russian, English'"), 995: ("'גופן גדול בלחיצה'", "'Large font in one tap'"), 996: ("'סכום הזמנה מינימלי'", "'Minimum order'"), 997: ("'אימות גיל 18+'", "'18+ age check'"), 998: ("'מחירים והנחות אישיים לכל לקוח'", "'Personal prices and discounts for each customer'"), 999: ("'היסטוריית הזמנות של הלקוח'", "'Customer order history'"), 1000: ("'חיבור למחסן ולמלאי'", "'Connection to warehouse and stock'"), 1001: ("'אפליקציה ללקוחות קבועים'", "'App for regular customers'"), 1002: ("'מחירון 2026 עם הזמנה לחנויות.'", "'2026 price list with ordering for stores.'"), 1003: ("'מחשבון רווח'", "'Profit calculator'"), 1004: ("'מחשב בשניות את רווח החנות לבקבוק, לקרטון ולכל ההזמנה — עם מע״מ ובלי.'", "'Calculates the store’s profit per bottle, per case and per order in seconds — with VAT and without.'"), 1005: ("'הבעלים לא יודעים בדיוק כמה הם מרוויחים על כל מוצר.'", "'The owner doesn’t know exactly how much each product earns.'"), 1006: ("'המחשבון מציג תוספת ואחוז מהמחיר זה לצד זה, מחשב מחיר ליחידה, לקרטון ולהזמנה, עם מע״מ 18% ובלי.'", "'The calculator shows markup and percentage of price side by side and works out unit, case and order prices, with 18% VAT and without.'"), 1007: ("'ברור אילו מוצרים משתלמים ואילו לא.'", "'It’s clear which products pay off and which don’t.'"), 1008: ("'רווח ליחידה, לקרטון ולהזמנה'", "'Profit per unit, case and order'"), 1009: ("'תוספת ואחוז מהמחיר זה לצד זה'", "'Markup and percentage of price side by side'"), 1010: ("'עם מע״מ 18% ובלי'", "'With 18% VAT and without'"), 1011: ("'חישוב לכל המבחר מקובץ'", "'Calculation for the whole range from a file'"), 1012: ("'המלצות מחיר'", "'Price recommendations'"), 1013: ("'השוואת ספקים'", "'Supplier comparison'"), 1014: ("'נבנה לחנויות ולסוכני מכירות.'", "'Built for stores and sales agents.'"), 1015: ("'אפליקציית סוכן — הזמנות ו-CRM בענן'", "'Agent app — orders and CRM in the cloud'"), 1016: ("'אפליקציה מלאה להזמנות: לקוחות, קטלוג, מלאי, היסטוריה. עובדת בענן, מוכנה לעבודה ולפיתוח לפי החברה שלכם.'", "'A complete ordering app: clients, catalog, stock, history. Works in the cloud, ready to use and to grow with your company.'"), 1017: ("'לקוחות, מחסן והזמנות מפוזרים במחברות ובצ׳אטים.'", "'Clients, stock and orders are scattered across notebooks and chats.'"), 1018: ("'אפליקציה אחת בענן: כרטיסי לקוחות, קטלוג עם מלאי, ביצוע הזמנה, היסטוריה ופעולות מהירות. הנתונים זמינים מכל מכשיר.'", "'One cloud app: client cards, catalog with stock, order entry, history and quick actions. Data is available from any device.'"), 1019: ("'כל העבודה של הסוכן במקום אחד, מהטלפון, והנתונים לא הולכים לאיבוד.'", "'All of the agent’s work in one place, on the phone, with nothing lost.'"), 1020: ("'כרטיסי לקוחות (CRM)'", "'Client cards (CRM)'"), 1021: ("'קטלוג ומלאי'", "'Catalog and stock'"), 1022: ("'ביצוע הזמנות'", "'Order entry'"), 1023: ("'היסטוריית הזמנות לכל לקוח'", "'Order history for each client'"), 1024: ("'פעולות מהירות'", "'Quick actions'"), 1025: ("'עבודה בענן'", "'Works in the cloud'"), 1026: ("'חיבור למשרד ולמחסן של החברה'", "'Connection to the company office and warehouse'"), 1027: ("'דוחות מכירות ולפי כל סוכן'", "'Sales reports, including per agent'"), 1028: ("'יעדים ותוכניות לסוכנים'", "'Targets and plans for agents'"), 1029: ("'חתימת לקוח ומסמכים'", "'Client signature and documents'"), 1030: ("'חיבור לעוזר לסוכן מכירות (מפה ומסלול)'", "'Connection to the sales agent assistant (map and route)'"), 1031: ("'אפליקציה מוכנה, אפשר להתחיל לעבוד.'", "'A finished app, ready to put to work.'"), 1032: ("'מוכן'", "'Ready'"), 1033: ("'מחשבון עם סרט'", "'Tape calculator'"), 1034: ("'מחשבון שזוכר כל צעד: סרט כמו על נייר, שורות עם שמות, חישוב שכר, מע״מ, מטבעות וייצוא.'", "'A calculator that remembers every step: a tape like on paper, named lines, salary calculation, VAT, currencies and export.'"), 1035: ("'מחשבון רגיל שוכח את החישוב, ואי אפשר לבדוק חשבון ארוך.'", "'A normal calculator forgets the calculation, and a long sum can’t be checked.'"), 1036: ("'כל שורה גלויה ומחושבת מיד: אפשר לשנות כל שורה, לקשר אותה לשורה אחרת ולחזור לחישוב. לצד זה — מחשבון שכר וסט כלים.'", "'Every line stays visible and recalculates instantly: change any line, link it to another and come back to the calculation. Alongside it — a salary calculator and a set of tools.'"), 1037: ("'חישוב שאפשר לבדוק, לשמור ולשלוח.'", "'A calculation you can check, save and send.'"), 1038: ("'סרט חישובים עם שמות שורות וסה״כ'", "'Calculation tape with line names and a total'"), 1039: ("'קישור בין שורות ושינוי כל שורה'", "'Linking lines and editing any line'"), 1040: ("'מחשבון שכר: נטו, מס, ביטוח לאומי'", "'Salary calculator: net pay, tax, social insurance'"), 1041: ("'כלים: מטבע, תשלומים, עמלה, מרווח, אחוזים, מע״מ'", "'Tools: currency, instalments, commission, margin, percentages, VAT'"), 1042: ("'שמירת חודשים והיסטוריית חישובים'", "'Saved months and calculation history'"), 1043: ("'עיצובים מתחלפים לכל האפליקציה'", "'Switchable designs for the whole app'"), 1044: ("'הקלדה קולית וייצוא'", "'Voice input and export'"), 1045: ("'עברית, רוסית, אנגלית; הנתונים רק במכשיר'", "'Hebrew, Russian, English; data stays on the device'"), 1046: ("'גרסה לעסקים עם חישובים משותפים'", "'Business version with shared calculations'"), 1047: ("'תבניות חישוב לפי מקצוע'", "'Calculation templates by profession'"), 1048: ("'חיבור להנהלת חשבונות'", "'Connection to accounting'"), 1049: ("'בהכנה ליציאה ל-App Store.'", "'Being prepared for release in the App Store.'"), 1050: ("'בקרוב ב-App Store'", "'Coming to App Store'"), 1051: ("'תוכנה'", "'Software'"), 1052: ("'Control Center — תוכנה לעסק'", "'Control Center — software for business'"), 1053: ("'תוכנה שמתאימה את עצמה ל-100 מקצועות: מספר ושרברב ועד עורך דין וצלם. לקוחות, תורים, מכירות, חוזים, כסף, אזור לקוח ואתר — בחלון אחד.'", "'Software that adapts to 100 professions: from hairdresser and plumber to lawyer and photographer. Clients, bookings, sales, contracts, money, client portal and website — in one window.'"), 1054: ("'לקוחות, פרויקטים וכסף מנוהלים בטבלאות ובצ׳אטים שונים.'", "'Clients, projects and money are kept in different spreadsheets and chats.'"), 1055: ("'בוחרים מקצוע — ומקבלים אזור עבודה שתפור עליו: תפריט משלו, מחירון עם מחירים לישראל, קטגוריות הוצאות ושיטת תשלום. משם התוכנה מובילה את הלקוח מפנייה ועד תשלום: משפך, תור, הצעה, חוזה בחתימה, חיובים, תזכורות ודוחות.'", "'You choose your profession and get a workspace tailored to it: its own menu, a price list with prices for Israel, expense categories and payment method. From there the software takes each client from enquiry to payment: pipeline, booking, proposal, signed contract, charges, reminders and reports.'"), 1056: ("'כל העסק בשליטה, עם תזכורות ודוחות.'", "'The whole business under control, with reminders and reports.'"), 1057: ("'100 מקצועות ב-7 תחומים: תורים, שיעורים, שטח, בנייה, פרויקטים, אירועים, ייעוץ'", "'100 professions in 7 areas: bookings, lessons, field work, construction, projects, events, consulting'"), 1058: ("'מקצוע משלכם: אפשר לכתוב כל מקצוע שאינו ברשימה'", "'Your own profession: type in any that isn’t on the list'"), 1059: ("'לכל מקצוע — תפריט, מחירון וקטגוריות הוצאות משלו'", "'For each profession — its own menu, price list and expense categories'"), 1060: ("'דף הבית: סיכום יומי, יעד חודשי, השבוע במספרים'", "'Home: daily summary, monthly goal, the week in numbers'"), 1061: ("'יומן, זימון תורים אונליין ואישור ביקורים'", "'Calendar, online booking and visit confirmation'"), 1062: ("'לקוחות, משפך מכירות, פניות'", "'Clients, sales pipeline, enquiries'"), 1063: ("'משימות, פרויקטים, עבודת צוות'", "'Tasks, projects, teamwork'"), 1064: ("'שירותים ומחירים, הצעות, חוזים בחתימת לקוח'", "'Services and prices, proposals, contracts signed by the client'"), 1065: ("'מנויים, תשלומים, הוצאות, דוחות ושימור לקוחות'", "'Subscriptions, payments, expenses, reports and client retention'"), 1066: ("'מסמכים, ציוד, ניטור אתרים'", "'Documents, equipment, website monitoring'"), 1067: ("'אזור לקוח: פרויקטים, מסמכים, חתימה, תשלומים'", "'Client portal: projects, documents, signing, payments'"), 1068: ("'אתר לבעל המקצוע: מחירון, ביקורות, פנייה, זימון תור'", "'Website for the professional: price list, reviews, enquiry form, online booking'"), 1069: ("'ארבעה סגנונות עיצוב, שלוש שפות'", "'Four design styles, three languages'"), 1070: ("'כניסה במפתח מכשיר, אימות דו-שלבי, יומן פעולות'", "'Sign-in with a device key, two-factor authentication, action log'"), 1071: ("'עוד מקצועות והתאמה עמוקה יותר לכל אחד'", "'More professions and deeper setup for each'"), 1072: ("'פונקציות מיוחדות לנישה (כמו באזור האירועים)'", "'Special features for a niche (like the events workspace)'"), 1073: ("'תשלום אונליין ווואטסאפ אוטומטי'", "'Online payment and automatic WhatsApp'"), 1074: ("'חיבור ל-Morning ול-iCount'", "'Connection to Morning and iCount'"), 1075: ("'אפליקציה לנייד'", "'Mobile app'"), 1076: ("'בשימוש בסטודיו Apps & Soul עצמו, בהכנה ללקוחות הראשונים. ההבדל העיקרי: התוכנה מתאימה את עצמה למקצוע, ולא המקצוע לתוכנה.'", "'Used by the Apps & Soul studio itself and being prepared for the first clients. The key difference: the software adapts to the profession, not the profession to the software.'"), 1077: ("'אטלס — מדריך עם מפה וסורק'", "'Atlas — a guide with a map and scanner'"), 1078: ("'אפליקציה גדולה עם מאגר משלה: מפת יצרנים, קטלוג, אנציקלופדיה, סורק תוויות וסומלייה אישי.'", "'A large app with its own database: producer map, catalog, encyclopedia, label scanner and a personal sommelier.'"), 1079: ("'צריך לאסוף כמות עצומה של מידע לאפליקציה אחת נוחה ויפה.'", "'A huge amount of information has to fit into one convenient and beautiful app.'"), 1080: ("'האפליקציה מאחדת מפה של תשעה אזורים, יצרנים, קטלוג יינות, משקאות חריפים וליקרים, אנציקלופדיה וסורק תוויות שמזהה בקבוק לפי תמונה.'", "'The app combines a map of nine regions, producers, a catalog of wines, spirits and liqueurs, an encyclopedia and a label scanner that recognises a bottle from a photo.'"), 1081: ("'דוגמה לפרויקט גדול עם מאגר נתונים משלו — גם בטלפון וגם במחשב.'", "'An example of a large project with its own database — on both phone and computer.'"), 1082: ("'מפה אינטראקטיבית של יצרנים לפי אזורים'", "'Interactive map of producers by region'"), 1083: ("'קטלוג: יינות, משקאות חריפים, ליקרים וקוקטיילים'", "'Catalog: wines, spirits, liqueurs and cocktails'"), 1084: ("'דפי יצרנים עם תמונות'", "'Producer pages with photos'"), 1085: ("'אנציקלופדיה בסגנון רומן-כרוניקה'", "'Encyclopedia written like a chronicle novel'"), 1086: ("'סורק תוויות: מזהה בקבוק לפי תמונה'", "'Label scanner: recognises a bottle from a photo'"), 1087: ("'סומלייה: התאמה למנה ולערב, טעימה עיוורת, יין היום'", "'Sommelier: pairing with a dish or an evening, blind tasting, wine of the day'"), 1088: ("'גרסה לטלפון ואתר נפרד למחשב'", "'Phone version and a separate site for computers'"), 1089: ("'מדריך כזה לכל תחום'", "'A guide like this for any field'"), 1090: ("'אזור אישי ומועדפים'", "'Personal account and favourites'"), 1091: ("'חנות בתוך האפליקציה'", "'A shop inside the app'"), 1092: ("'רוסית ואנגלית'", "'Russian and English'"), 1093: ("'אטלס האלכוהול הישראלי, בעברית.'", "'Israeli Alcohol Atlas, in Hebrew.'"), 1094: ("'Discovery Radar — רעיונות לעסק'", "'Discovery Radar — ideas for business'"), 1095: ("'מציג תגלית מפתיעה, מסביר אותה במילים פשוטות ומציע איך ליישם אותה בעסק.'", "'Shows a surprising discovery, explains it in plain words and suggests how to use it in business.'"), 1096: ("'רעיונות טובים הולכים לאיבוד בין אלפי כתבות וסרטונים.'", "'Good ideas get lost among thousands of articles and videos.'"), 1097: ("'האפליקציה בוחרת תגלית, מסבירה אותה ומציעה יישום. מצב „עזור לי לפתור משימה״ נותן חישוב מוכן: למשל פחות נסיעות או פחות טעויות בהזמנות.'", "'The app picks a discovery, explains it and suggests an application. The “Help me solve a problem” mode gives a ready calculation: for example, less driving or fewer order mistakes.'"), 1098: ("'רעיון שמגיע מיד עם תועלת וחישוב.'", "'An idea that comes with a benefit and a calculation.'"), 1099: ("'„תפתיע אותי״: תגלית ורעיון ליישום'", "'“Surprise me”: a discovery and an idea for using it'"), 1100: ("'„עזור לי לפתור משימה״ עם חישוב מוכן'", "'“Help me solve a problem” with a ready calculation'"), 1101: ("'מפת רעיונות אישית ושמורים'", "'Your own idea map and saved items'"), 1102: ("'רעיונות לתחום מסוים'", "'Ideas for a specific industry'"), 1103: ("'עבודת צוות על רעיונות'", "'Teamwork on ideas'"), 1104: ("'בדוגמה לימודית מסלול של 10 נקודות מתקצר ב-54%.'", "'In a training example, a 10-stop route gets 54% shorter.'"), 1105: ("'קטלוג מסחרי לספק'", "'Commercial catalog for a supplier'"), 1106: ("'קטלוג שלא מתביישים לשלוח ללקוח: תמונות, תיאורים ומחלקות, להדפסה ולשליחה.'", "'A catalog you’re proud to send to clients: photos, descriptions and sections, for print and sharing.'"), 1107: ("'לספק צריך קטלוג יפה של כל המבחר.'", "'The supplier needs a beautiful catalog of the whole range.'"), 1108: ("'קטלוג עם תמונות, תיאורים ומחלקות לפי סוגי מוצרים, מעוצב להדפסה ולשליחה ב-PDF.'", "'A catalog with photos, descriptions and sections by product type, laid out for print and sending as a PDF.'"), 1109: ("'הלקוחות רואים את כל המבחר בקובץ אחד.'", "'Clients see the whole range in one file.'"), 1110: ("'תמונה ותיאור לכל מוצר'", "'Photo and description for every product'"), 1111: ("'מחלקות לפי קטגוריות'", "'Sections by category'"), 1112: ("'PDF להדפסה ולשליחה'", "'PDF for print and sharing'"), 1113: ("'קטלוג-אתר עם הזמנה'", "'Catalog website with ordering'"), 1114: ("'עדכון מחירים מקובץ'", "'Price updates from a file'"), 1115: ("'גרסאות בכמה שפות'", "'Versions in several languages'"), 1116: ("'קטלוג קעואר: ערק, יינות, בירות, ליקרים — 83 עמודים.'", "'Kawar catalog: arak, wines, beers, liqueurs — 83 pages.'"), 1117: ("'קטלוג בטלפון'", "'Catalog on the phone'"), 1118: ("'קטלוג יפה שנפתח בקישור: מחלקות, תמונות, תיאורים.'", "'A beautiful catalog that opens from a link: sections, photos, descriptions.'"), 1119: ("'החנות צריכה קטלוג נוח שאפשר לשלוח ללקוח.'", "'The store needs a convenient catalog it can send to customers.'"), 1120: ("'קטלוג לטלפון עם מחלקות לפי סוגי מוצרים.'", "'A phone catalog with sections by product type.'"), 1121: ("'ללקוח שולחים קישור אחד.'", "'Customers get a single link.'"), 1122: ("'גרסה לטלפון'", "'Phone version'"), 1123: ("'מחלקות לפי סוגי מוצרים'", "'Sections by product type'"), 1124: ("'הזמנה ישר מהקטלוג'", "'Ordering straight from the catalog'"), 1125: ("'חיפוש ומסננים'", "'Search and filters'"), 1126: ("'עדכון בלי מתכנת'", "'Updates without a programmer'"), 1127: ("'קטלוג יינות ומשקאות חריפים „גפנים בוגרות״.'", "'Wine and spirits catalog “Old Vines”.'"), 1128: ("'פאנל לרשת חנויות'", "'Panel for a chain of stores'"), 1129: ("'פאנל אחד לכמה חנויות: מוצרים, קטגוריות, מחסן, הזמנות, לקוחות, מבצעים ודוחות.'", "'One panel for several stores: products, categories, warehouse, orders, customers, promotions and reports.'"), 1130: ("'בעל הרשת צריך לראות את כל המוצרים ולהבין איפה חסרים תמונות, שמות ומחירים.'", "'A chain owner needs to see every product and know where photos, names and prices are missing.'"), 1131: ("'הפאנל מציג את מוכנות הקטלוג בכל חנות, מנהל מוצרים, מחסן, הזמנות ודוחות, ומייבא ומייצא קבצים.'", "'The panel shows catalog readiness for each store, manages products, stock, orders and reports, and imports and exports files.'"), 1132: ("'רואים מה מוכן ומה צריך להשלים, בכל חנות.'", "'You can see what’s done and what’s left, store by store.'"), 1133: ("'סקירה: כמה מוצרים, עם תמונה ובלי, בלי מחיר'", "'Overview: how many products, with and without photos, without price'"), 1134: ("'מוצרים וקטגוריות של כל החנויות'", "'Products and categories of all stores'"), 1135: ("'מחסן'", "'Warehouse'"), 1136: ("'ייבוא וייצוא קבצים לאתר'", "'Import and export of files for the site'"), 1137: ("'הזמנות, לקוחות, מבצעים, דוחות'", "'Orders, customers, promotions, reports'"), 1138: ("'רוסית ועברית'", "'Russian and Hebrew'"), 1139: ("'הרשאות למנהלי כל חנות'", "'Permissions for each store manager'"), 1140: ("'העברת סחורה בין חנויות'", "'Moving stock between stores'"), 1141: ("'חיבור לקופה'", "'Connection to the till'"), 1142: ("'פאנל לשלוש חנויות: כמעט 4,800 מוצרים.'", "'Panel for three stores: almost 4,800 products.'"), 1143: ("'שירות'", "'Service'"), 1144: ("'עיבוד תמונות מוצרים'", "'Product photo editing'"), 1145: ("'תמונות מהמחסן הופכות לתמונות כמו בחנות גדולה: בלי רקע, המוצר ישר וגדול.'", "'Warehouse photos become big-store photos: background removed, product straight and large.'"), 1146: ("'התמונות צולמו במחסן, בזווית ועל רקעים שונים. הקטלוג נראה מרושל.'", "'Photos were taken in the warehouse, at an angle and on different backgrounds. The catalog looks sloppy.'"), 1147: ("'הרקע מוסר, הפרספקטיבה וההטיה מיושרות, המוצר גדול במרכז, בהיר וחד יותר.'", "'The background is removed, perspective and tilt are straightened, the product is placed large in the centre, brighter and sharper.'"), 1148: ("'הקטלוג נראה כמו בחנות גדולה.'", "'The catalog looks like a big store’s.'"), 1149: ("'הסרת רקע'", "'Background removal'"), 1150: ("'יישור פרספקטיבה והטיה'", "'Perspective and tilt correction'"), 1151: ("'סגנון אחיד לכל הקטלוג'", "'One style for the whole catalog'"), 1152: ("'סימון אילו תמונות עדיף לצלם מחדש'", "'Marking which photos are better reshot'"), 1153: ("'עיבוד מוצרים חדשים כשהם מגיעים'", "'Editing new products as they arrive'"), 1154: ("'תמונות לפרסום ולרשתות'", "'Photos for ads and social media'"), 1155: ("'1,795 תמונות הובאו למראה אחיד.'", "'1,795 photos brought to one look.'"), 1156: ("'בדיקת אתר'", "'Website audit'"), 1157: ("'ניתוח ברור: למה האתר לא מביא פניות ומה לתקן קודם.'", "'A clear breakdown: why the site brings no enquiries and what to fix first.'"), 1158: ("'יש אתר, אבל מעט פניות, ולא ברור למה.'", "'There is a website, but few enquiries, and it’s unclear why.'"), 1159: ("'בדיקה טכנית ושיווקית: מהירות, אבטחה, עמודי חובה, טקסטים, אמון ותוכנית פיתוח.'", "'A technical and marketing review: speed, security, required pages, texts, trust and a growth plan.'"), 1160: ("'רשימה: מה לתקן מיד, מה אחר כך ומה זה ייתן.'", "'A list: what to fix now, what later, and what it will bring.'"), 1161: ("'מדידות מהירות בטלפון ובמחשב'", "'Speed measurements on phone and computer'"), 1162: ("'בעיות לפי דחיפות: חוק, מכירות, איכות'", "'Issues by urgency: law, sales, quality'"), 1163: ("'טקסטים, תמונות, ביקורות, מחירים'", "'Texts, images, reviews, prices'"), 1164: ("'תוכנית פיתוח עם חישוב פניות'", "'Growth plan with an enquiry estimate'"), 1165: ("'תיקון הממצאים מקצה לקצה'", "'Fixing the findings end to end'"), 1166: ("'קידום בגוגל'", "'Google promotion'"), 1167: ("'בקרה חודשית'", "'Monthly monitoring'"), 1168: ("'בדיקת אתר של חברת אירועים.'", "'Audit of an events company website.'"), 1169: ("'פרופיל'", "'Profile'"), 1170: ("'אזור עבודה לפי מקצוע'", "'Workspace for a profession'"), 1171: ("'תוכנה שמותאמת לעסק מסוים. לדוגמה — אירועים: תוכנית יום, ציוד, צוות, כסף.'", "'Software tailored to a specific business. For example, events: day plan, equipment, crew, money.'"), 1172: ("'חברה צריכה לזכור הקמה, ציוד, צוות ותשלום לכל אירוע.'", "'A company has to keep set-up, equipment, crew and payment in mind for every event.'"), 1173: ("'אזור עבודה לפי מקצוע: תוכנית יום ולפי דקות, ציוד עם מחסן, צוות, כסף והתראה על התנגשות הזמנות.'", "'A workspace for the profession: day plan and minute-by-minute plan, equipment with stock, crew, money and a booking-conflict warning.'"), 1174: ("'שום דבר לא מתנגש ולא נשכח.'", "'Nothing clashes and nothing is forgotten.'"), 1175: ("'תוכנית יום ותוכנית לפי דקות'", "'Day plan and minute-by-minute plan'"), 1176: ("'ציוד ומחסן, התראה על התנגשות הזמנה'", "'Equipment and stock, booking-conflict warning'"), 1177: ("'צוות וקבלני משנה'", "'Crew and subcontractors'"), 1178: ("'חבילה, מקדמה, יתרה'", "'Package, deposit, balance'"), 1179: ("'אזור כזה לכל מקצוע'", "'A workspace like this for any profession'"), 1180: ("'אזור ללקוחות'", "'Portal for clients'"), 1181: ("'אפליקציה לנייד לצוות'", "'Mobile app for the crew'"), 1182: ("'פרופיל לחברת אירועים בתוך Control Center.'", "'Profile for an events company inside Control Center.'"), 1183: ("'משחק'", "'Game'"), 1184: ("'משחק לטלפון'", "'Phone game'"), 1185: ("'משחק חי שנפתח בקישור ועובד ישר בדפדפן של הטלפון.'", "'A lively game that opens from a link and runs right in the phone browser.'"), 1186: ("'להראות שאפשר לבנות משחק בלי הורדה מחנות אפליקציות.'", "'Show that a game can be made without downloading from an app store.'"), 1187: ("'משחק ארקייד עם גרפיקה צבעונית, עובד בדפדפן.'", "'An arcade game with bright graphics that runs in the browser.'"), 1188: ("'דוגמה לפרויקט בידור.'", "'An example of an entertainment project.'"), 1189: ("'עובד בדפדפן של הטלפון'", "'Runs in the phone browser'"), 1190: ("'גרפיקה צבעונית'", "'Bright graphics'"), 1191: ("'משחק-פרסומת לעסק עם פרסים'", "'Promotional game for a business with prizes'"), 1192: ("'טבלת שיאים'", "'High-score table'"), 1193: ("'גרסה ל-App Store ול-Google Play'", "'Version for the App Store and Google Play'"), 1194: ("'„בום-ארנה״.'", "'“Boom Arena”.'"), 1195: ('<dt>מה זה עושה</dt>', '<dt>What it does</dt>'), 1196: ('<dt>התוצאה</dt>', '<dt>Result</dt>'), 1197: ('<dt>מה זה יודע היום</dt>', '<dt>What it can do now</dt>'), 1198: ('<dt>↗ אפשר לפתח</dt>', '<dt>↗ Can grow into</dt>'), 1199: ('<b>דוגמה מהחיים:</b>', '<b>Real-life example:</b>'), 1200: ('<p class="wlead">כל עבודה כאן היא בסיס. <b>אנחנו מפתחים אותה למשימה שלכם:</b> כל מורכבות, כל מטרה.</p>', '<p class="wlead">Every project here is a foundation. <b>We develop it for your task:</b> any complexity, any goal.</p>'), 1201: ('<p class="big1">אני יזם ומייסד הסטודיו Apps &amp; Soul.</p>', '<p class="big1">I’m an entrepreneur and the founder of the Apps &amp; Soul studio.</p>'), 1202: ('<p>אני הופך רעיונות לתוכנות שעובדות. עד היום יש לי יותר מ-20 פרויקטים: חנויות אונליין עם אלפי מוצרים, פאנלי ניהול, עוזר להעלאת מוצרים עם מאגר ברקודים משלנו, אפליקציית הזמנות עם CRM בענן, עוזר לסוכן מכירות, תוכנה לספירת מלאי בחנות, קטלוגים מסחריים, מחשבון עם סרט, אטלס-מדריך ותוכנה לעסק שמתאימה את עצמה ל-100 מקצועות.</p>\n    <p>חלק בניתי ללקוחות, וחלק התחילו כרעיון שלי: ראיתי בעיה ובניתי פתרון. ואני לא עוצר במוכן: כל תוכנה אפשר לפתח לכל משימה ולכל רמת מורכבות.</p>', '<p>I turn ideas into working software. Today I have more than 20 projects: online stores with thousands of products, admin panels, a product upload assistant with our own barcode database, an ordering app with a cloud CRM, a sales agent assistant, a store stock count app, commercial catalogs, a tape calculator, an atlas guide, and business software that adapts to 100 professions.</p>\n    <p>Some I built for clients, and some started as my own idea: I saw a problem and built a solution. And I don’t stop at done: every program can be developed for any task and any level of complexity.</p>'), 1203: ('<small>מושאילוב דוד · יזם ומייסד</small>', '<small>Mushailov David · entrepreneur and founder</small>'), 1204: ('<span>יזם, מייסד Apps &amp; Soul</span>', '<span>entrepreneur, founder of Apps &amp; Soul</span>'), 1205: ("{'פועל':'ok','מוכן':'ok','שירות':'ok','בהשקה':'go','בקרוב ב-App Store':'go','בפיתוח':'wip'}", "{'Live':'ok','Ready':'ok','Service':'ok','Launching':'go','Coming to App Store':'go','In development':'wip'}")})

T.update({1206: ('שלוש חבילות לפי גודל העסק ותוספות להן. המחיר תלוי במשימה: את המחיר המדויק ולוח הזמנים אמסור אחרי שיחה קצרה.', 'Three packages by business size, plus add-ons. The cost depends on the task: I’ll give the exact price and timeline after a short call.'), 1207: (' תמורת המלצה ואישור להציג את הפרויקט. את המחיר המדויק אמסור אחרי שיחה קצרה.', ' in exchange for a review and permission to show the project. I’ll give the exact cost after a short call.'), 1208: ('ליווי — במנוי או בעבודות חד־פעמיות. המחיר נקבע מראש ונרשם בתוכנית.', 'Support is by subscription or one-off jobs. The cost is agreed in advance and written into the plan.'), 1209: ('המחיר תלוי במשימה: כמה עמודים או מוצרים, אילו פונקציות ומה צריך לחבר. את המחיר המדויק ולוח הזמנים אמסור אחרי שיחה קצרה. התשלום בשלבים: 40% בהתחלה, 40% אחרי הסקיצה, 20% בהשקה.', 'The cost depends on the task: how many pages or products, which features and what needs connecting. I’ll give the exact price and timeline after a short call. Payment in stages: 40% at the start, 40% after the mockup, 20% at launch.'), 1210: ('<p>לפני תחילת העבודה תקבלו תוכנית כתובה: מה כלול, כמה זה עולה ובאיזה לוח זמנים. כל מה שלא נכלל בתוכנית מתומחר בנפרד ורק בהסכמתכם.</p>', '<p>Before work starts you get a written plan: what’s included, what it costs and the timeline. Anything outside the plan is priced separately and only with your consent.</p>')})

T.update({1211: ('חינם', 'Free'), 1212: ('בדיקה חינם לאתר שלכם', 'A free review of your website'), 1213: ('שלחו קישור לאתר, לחנות או לעמוד ברשתות החברתיות. אסתכל עליו בעיני לקוח ואכתוב לכם בוואטסאפ שלוש עצות מעשיות: מה מפריע למכור ומה כדאי לתקן קודם.', 'Send a link to your website, store or social media page. I’ll look at it through a customer’s eyes and send you three specific tips on WhatsApp: what is getting in the way of sales and what to fix first.'), 1214: ('בלי התחייבות. עדיין אין אתר? שלחו קישור לאינסטגרם או לפייסבוק.', 'No obligation. No website yet? Send a link to your Instagram or Facebook.'), 1215: ('קישור לאתר או לעמוד שלכם', 'Link to your website or page'), 1216: ('למשל, mysite.co.il', 'for example, mysite.co.il'), 1217: ('שלום דוד! אשמח לבדיקה חינם לאתר:', 'Hello David! I’d like a free website review:'), 1218: ('לקבל בדיקה בוואטסאפ ', 'Get the review on WhatsApp '), 1219: ('מידע שימושי', 'Useful reading'), 1220: ('מאמרים לבעלי עסקים', 'Articles for business owners'), 1221: ('בקצרה ובכנות: מה כדאי לדעת לפני שמזמינים אתר או אפליקציה.', 'Short and honest: what is worth knowing before you order a website or an app.'), 1222: ('לקריאת המאמר ', 'Read the article '), 1223: ('articles/he/', 'articles/en/'), 1224: ('אתר, אפליקציה על המסך או אפליקציה ב-App Store?', 'A website, a home-screen app or an App Store app?'), 1225: ('במה הם שונים, כמה עולה התחזוקה של כל אחד ומאיפה נכון להתחיל.', 'How they differ, what each costs to keep running and where it makes sense to start.'), 1226: ('אתר משלכם או בונה אתרים כמו Wix ו-Shopify', 'Your own website or a builder like Wix and Shopify'), 1227: ('השוואה כנה: מתי בונה אתרים מספיק, ומתי אתר משלכם משתלם יותר.', 'An honest comparison: when a builder is enough and when your own site pays off.'), 1228: ('מה צריך אתר של חנות כדי למכור', 'What a store website needs in order to sell'), 1229: ('רשימת בדיקה של עשרה סעיפים שאפשר לבדוק באתר שלכם בעשר דקות.', 'A ten-point checklist you can run on your own site in ten minutes.')})

